#include <iostream>
#include <map>
#include <set>
#include <string>
#include <vector>

int main() {
    // vector: order kept, duplicates allowed
    std::vector<std::string> words = {"banana", "apple", "banana"};
    std::cout << "vector size: " << words.size() << std::endl;

    // set: unique values, stored sorted
    std::set<std::string> unique(words.begin(), words.end());
    std::cout << "set size: " << unique.size() << std::endl;

    // map: key -> value, sorted by key
    std::map<std::string, int> prices;
    prices["apple"] = 10;
    prices["banana"] = 6;
    std::cout << "map size: " << prices.size()
              << ", apple: " << prices["apple"] << std::endl;
    return 0;
}

#include <iostream>
#include <vector>

int main() {
    std::vector<int> v;
    std::cout << "start: size=" << v.size()
              << " capacity=" << v.capacity() << std::endl;

    for (int i = 1; i <= 5; i++) {
        v.push_back(i * 10);
    }
    std::cout << "pushed 5: size=" << v.size()
              << " capacity=" << v.capacity() << std::endl;

    v.insert(v.begin(), 0);
    std::cout << "after insert: size=" << v.size() << std::endl;

    v.erase(v.begin() + 1, v.begin() + 3);
    std::cout << "after erase: size=" << v.size() << std::endl;

    bool head = true;
    for (std::vector<int>::iterator it = v.begin(); it != v.end(); ++it) {
        if (!head) std::cout << ' ';
        std::cout << *it;
        head = false;
    }
    std::cout << std::endl;

    v.reserve(100);
    std::cout << "after reserve: size=" << v.size()
              << " capacity=" << v.capacity() << std::endl;
    return 0;
}

#include <iostream>
#include <vector>

int main() {
    std::vector<int> v;
    v.reserve(4);              // allocate memory ahead of time
    std::cout << "reserve: " << v.capacity() << std::endl;

    for (int i = 0; i < 4; i++) {
        v.push_back(i + 1);    // no relocation: within the reserve
    }
    std::cout << "size: " << v.size()
              << " capacity: " << v.capacity() << std::endl;

    v.resize(8, 0);            // extend with zeros
    std::cout << "resize: " << v.size() << std::endl;

    std::cout << v.at(0) << ' ' << v.at(4) << ' ' << v.back() << std::endl;
    return 0;
}

#include <algorithm>
#include <cctype>
#include <iostream>
#include <string>

// Predicate: function returning bool for count_if
bool isVowel(char c) {
    char lower = static_cast<char>(std::tolower(c));
    return lower == 'a' || lower == 'e' || lower == 'i' ||
           lower == 'o' || lower == 'u';
}

int main() {
    std::string word = "Programming";

    std::cout << "vowels: "
              << std::count_if(word.begin(), word.end(), isVowel) << std::endl;

    std::string upper = word;
    for (char& c : upper) {
        c = static_cast<char>(std::toupper(c));
    }
    std::cout << upper << std::endl;

    std::reverse(word.begin(), word.end());
    std::cout << word << std::endl;

    std::cout << "g: " << std::count(word.begin(), word.end(), 'g')
              << std::endl;
    return 0;
}

#include <iostream>
#include <map>
#include <set>
#include <string>

int main() {
    std::map<std::string, int> scores;
    scores["Clara"] = 82;
    scores["Anna"] = 90;
    scores["Boris"] = 75;

    std::cout << "Boris: " << scores["Boris"] << std::endl;
    std::cout << "has Dan: " << scores.count("Dan") << std::endl;

    for (const auto& entry : scores) {
        std::cout << entry.first << " -> " << entry.second << std::endl;
    }

    std::set<int> seen = {5, 3, 5, 3, 8};
    std::cout << "set size: " << seen.size() << std::endl;
    for (int x : seen) {
        std::cout << x << std::endl;
    }
    return 0;
}

#include <iostream>
#include <iterator>
#include <vector>

int main() {
    std::vector<int> v = {10, 20, 30, 40, 50};

    std::vector<int>::iterator fwd = v.begin();
    std::cout << *fwd << std::endl;

    fwd += 2;
    std::cout << *fwd << std::endl;

    std::vector<int>::reverse_iterator back = v.rbegin();
    std::cout << *back << ' ' << *(back + 4) << std::endl;

    for (auto it = v.begin(); it != v.end(); ++it) {
        *it *= 2;                    // change through the iterator
    }
    std::cout << v[0] << ' ' << v[4] << std::endl;

    std::cout << std::distance(v.begin(), v.begin() + 3) << std::endl;
    return 0;
}

#include <iostream>
#include <set>

int main() {
    std::set<int> s = {30, 10, 20};

    // Same iterator protocol: set walks sorted, not by index
    for (std::set<int>::const_iterator it = s.cbegin(); it != s.cend(); ++it) {
        std::cout << *it << std::endl;
    }

    // Range-for is the same loop in a shorter spelling
    for (int x : s) {
        std::cout << "value " << x << std::endl;
    }
    return 0;
}

#include <algorithm>
#include <iostream>
#include <vector>

bool isEven(int x) {
    return x % 2 == 0;
}

int square(int x) {
    return x * x;
}

int main() {
    std::vector<int> data = {3, 8, 2, 8, 6, 8};

    auto pos = std::find(data.begin(), data.end(), 6);
    if (pos != data.end()) {
        std::cout << "index of 6: " << pos - data.begin() << std::endl;
    } else {
        std::cout << "6 not found" << std::endl;
    }

    std::cout << "evens: "
              << std::count_if(data.begin(), data.end(), isEven) << std::endl;

    std::vector<int> squared(data.size());
    std::transform(data.begin(), data.end(), squared.begin(), square);

    bool head = true;
    for (int x : squared) {
        if (!head) std::cout << ' ';
        std::cout << x;
        head = false;
    }
    std::cout << std::endl;
    return 0;
}

#include <algorithm>
#include <iostream>
#include <string>
#include <vector>

int main() {
    // No capture: pure two-argument function
    auto add = [](int a, int b) { return a + b; };
    std::cout << add(2, 3) << std::endl;

    int offset = 10;
    auto shift = [offset](int x) { return x + offset; };   // by value
    std::cout << shift(5) << std::endl;

    int calls = 0;
    auto log = [&calls](const std::string& msg) {          // by reference
        ++calls;
        std::cout << msg << " #" << calls << std::endl;
    };
    log("start");
    log("finish");

    std::vector<int> v = {1, 5, 2};
    std::sort(v.begin(), v.end(),
              [](int a, int b) { return a > b; });         // comparator
    for (int x : v) {
        std::cout << x << std::endl;
    }
    return 0;
}

#include <functional>
#include <iostream>
#include <queue>

int main() {
    std::priority_queue<int> pq;
    pq.push(20);
    pq.push(5);
    pq.push(45);

    std::cout << "size: " << pq.size() << std::endl;
    std::cout << "top: " << pq.top() << std::endl;

    std::cout << "order:";
    while (!pq.empty()) {
        std::cout << ' ' << pq.top();
        pq.pop();
    }
    std::cout << std::endl;

    // "Min-heap": the smallest value on top
    std::priority_queue<int, std::vector<int>, std::greater<int>> minPq;
    minPq.push(20);
    minPq.push(5);
    std::cout << "min top: " << minPq.top() << std::endl;
    return 0;
}
